using UnityEngine;
using System.Collections;
using System.Collections.Generic;
public partial class DungeonPrototype {
 readonly HashSet<int> combatSummons=new HashSet<int>();
 List<SpeciesSpawnWeight> MakongSummonCandidates(){var result=new List<SpeciesSpawnWeight>();foreach(var row in MakongSpecialSettings.Current.helperSpecies??new SpeciesSpawnWeight[0]){if(row==null||row.weight<=0)continue;var definition=EnemyCharacterCatalog.Current.FindId(row.speciesId);int kind=ArrayIndex(row.speciesId);if(definition!=null&&!definition.reservedForEvents&&definition.category==EnemyRank.Enemigo&&kind>=0&&kind<EnemyRoster.Mimic)result.Add(row);}return result;}
 bool MakongSummonCell(int owner,out Vector2Int cell){var region=slots[owner].origin;for(int y=1;y<map.Length-1;y++)for(int x=1;x<map[y].Length-1;x++){var candidate=new Vector2Int(x,y);if(candidate!=position&&Open(candidate)&&RegionAt(candidate)==region&&!Occupied(candidate)&&!ReservedCell(candidate)){cell=candidate;return true;}}cell=position;return false;}
 int MakongHelperCount(int index){int count=0;foreach(int other in encounter)if(other!=index&&enemyObjects[other]!=null&&enemyLives[other]>0)count++;return count;}
 MakongContext MakongContextFor(int index,MakongEnemyVisual visual){Vector2Int free;return new MakongContext{hp=enemyLives[index],maximumHP=enemyObjects[index].GetComponent<EnemyCombatStats>().maximumHP,helpers=MakongHelperCount(index),participants=encounter.Count,edibleHelper=MakongCompanion(index,visual.Tactics.Turn+1)>=0,canSummon=enemyObjects[index].GetComponent<EnemyCombatStats>().level>1&&MakongSummonCandidates().Count>0&&MakongSummonCell(index,out free)};}
 MakongAction DecideMakong(int index,MakongEnemyVisual visual){var action=visual.Tactics.Decide(MakongContextFor(index,visual),MakongSpecialSettings.Current,()=>Random.value);if(MakongSpecialSettings.Current.debugDecisions)Debug.Log("MAKONG turno "+visual.Tactics.Turn+" — "+action+": "+visual.Tactics.Reason,visual);return action;}
 IEnumerator RunMakongAction(int index,MakongEnemyVisual visual,MakongAction action){Bark(EnemyBarkCategory.Special);if(action==MakongAction.Earthquake)yield return MakongJump(index,visual);else if(action==MakongAction.Swallow){int companion=MakongCompanion(index,visual.Tactics.Turn);if(companion>=0)yield return MakongSwallow(index,companion,visual);}else if(action==MakongAction.Summon)yield return MakongSummon(index,visual);}
 IEnumerator MakongSummon(int index,MakongEnemyVisual visual){var settings=MakongSpecialSettings.Current;visual.Hold("swallow_prepare_0");message="MAKONG llama a sus ayudantes…";yield return new WaitForSeconds(settings.swallowFrameSeconds*2);
  var candidates=MakongSummonCandidates();var weights=new double[candidates.Count];for(int n=0;n<candidates.Count;n++)weights[n]=candidates[n].weight;
  int limit=Mathf.Min(Mathf.Clamp(settings.maximumHelpers,0,2)-MakongHelperCount(index),3-encounter.Count);int wanted=Mathf.Min(limit,Random.value<settings.twoHelpersProbability?2:1);var boss=enemyObjects[index].GetComponent<EnemyCombatStats>();
  for(int n=0;n<wanted;n++){Vector2Int cell;if(!MakongSummonCell(index,out cell)||candidates.Count==0)break;int choice=EnemyZoneSettings.Select(weights,Random.value);if(choice<0)break;int level=Mathf.Clamp(Random.Range(Mathf.Max(1,settings.helperMinimumLevel),Mathf.Max(settings.helperMinimumLevel,settings.helperMaximumLevel)+1),1,boss.level-1);
   var placement=new PlacedEnemyDefinition{speciesId=candidates[choice].speciesId,cell=cell,fixedLevel=level,randomLevel=false,respawn=false,unique=true,countsTowardLimit=false,allowInSafeArea=true,trigger=EncounterTrigger.InteractiveEvent};int before=enemyObjects.Count;AddEnemy(cell,visualKind:ArrayIndex(placement.speciesId),origin:slots[index].origin,placement:placement);if(before==enemyObjects.Count)continue;int helper=enemyObjects.Count-1;combatSummons.Add(helper);var root=enemyObjects[helper];var marker=root.AddComponent<MakongSummonedHelper>();marker.ownerInstanceId=boss.instanceId;marker.summonedOnTurn=visual.Tactics.Turn;
   bool leftOccupied=false;foreach(int other in encounter)if(other!=index&&enemyObjects[other]!=null&&Vector3.Dot(enemyObjects[other].transform.position-formationCenter,formationRight)<0)leftOccupied=true;int side=leftOccupied?1:-1;
   float distance=EnemySpaceLayout.Width(EnemyRoster.Makong,EnemySizeSettings.Current)*.5f+EnemySpaceLayout.Width(root.GetComponent<GhostEnemyVisual>().Kind,EnemySizeSettings.Current)*.5f+.4f;Vector3 target=formationCenter+formationRight*side*distance;
   encounter.Add(helper);encounterHomes[helper]=root.transform.position;encounterScales[helper]=root.transform.localScale;root.transform.localScale=Vector3.one;root.transform.position=target+formationForward*1.5f;root.transform.LookAt(new Vector3(view.transform.position.x,root.transform.position.y,view.transform.position.z));
   EnsureBattleStage();float cameraDistance=Mathf.Max(4.8f,BattleWidth*.5f/(Mathf.Tan(34*Mathf.Deg2Rad)*view.aspect)+.8f);Vector3 cameraFrom=view.transform.position,cameraTo=BattleStageOrigin+new Vector3(0,1.5f,-cameraDistance);Vector3 from=root.transform.position;
   for(float t=0;t<.3f;t+=Time.deltaTime){float k=Mathf.SmoothStep(0,1,t/.3f);root.transform.position=Vector3.Lerp(from,target,k);view.transform.position=Vector3.Lerp(cameraFrom,cameraTo,k);yield return null;}root.transform.position=target;view.transform.position=cameraTo;
  }
  visual.EndSpecial();
 }
 void ClearCombatSummons(){foreach(int index in combatSummons){if(index>=enemyObjects.Count)continue;if(enemyObjects[index]!=null){Destroy(enemyObjects[index]);enemyObjects[index]=null;}respawnAt[index]=-1;defeatedEnemies.Remove(index);}combatSummons.Clear();}
 void EnsureMakongPlacementAfterLoad(DungeonSaveData data){if(RegionMap==null)return;foreach(var placement in RegionMap.placedEnemies){if(placement==null||placement.speciesId!="Makong"&&!placement.id.StartsWith("makong.key.guard.")||placement.trigger!=EncounterTrigger.OnDungeonStart)continue;bool recorded=false;foreach(var record in data.enemies)if(record.placementId==placement.id){recorded=true;break;}if(!recorded&&!triggeredEncounters.Contains(placement.id))SpawnPlacement(placement);}}
}
